309	function checkInvocation(invocation: ShellInvocation): GuardVerdict {
310	  const cwd = invocation.workingDirectory?.trim();
311	  if (cwd) {
312	    const reason = outsideRepository(cwd);
313	    if (reason) return { allow: false, reason };
314	  }
315	
316	  const gitCommand = findMutatingGitCommand(invocation.command);
317	  if (gitCommand) {
318	    // Two different answers, because there are two different situations and the
319	    // single blanket message sent an agent hunting for a tool that does not
320	    // exist. `commit`/`push`/`checkout` and the rest of the everyday ones have a
321	    // route; `config`, `stash`, `clean` and `bisect` do not, and saying so is
322	    // more useful than naming a family of tools with nothing in it for them.
323	    const routed = ROUTED_GIT_COMMANDS.has(gitCommand);
324	    return {
325	      allow: false,
326	      reason: routed
327	        ? `Raw 'git ${gitCommand}' is disabled. Use the github tools for Git mutations and branch synchronization.` +
328	          (ROUTED_GIT_ADVICE[gitCommand] ?? "")
329	        : `Raw 'git ${gitCommand}' is disabled, and there is no MCP tool for it: this run does not do that. `
330	          + `Commit with commit_and_push; read-only inspection (status, diff, log) runs normally.`,
331	    };
332	  }
333	
334	  const [environPattern, environReason] = PROCESS_ENVIRONMENT_READ;
335	  if (environPattern.test(invocation.command)) return { allow: false, reason: environReason };
336	
337	  for (const program of invokedPrograms(invocation.command)) {
338	    const reason = ROUTING_RULES[program];
339	    if (reason) return { allow: false, reason };
340	  }
341	  return ALLOWED;
342	}
