/** The commands a command line runs inside substitutions. */
function substituted(command: string): string[] {
  const found: string[] = [];
  for (let i = 0; i < command.length; i += 1) {
    if (command[i] === "$" && command[i+1] === "(") {
      const end = matchingParen(command, i + 1);
      if (end !== -1) { found.push(command.slice(i + 2, end)); i = end; }
